INSERT INTO `pbb_email_msg` VALUES (1,'Change password request','welcome [MySBB]username[/MySBB]<br /><br />You have requested to change your password in the forum. To complete and change the steps please click on this link:<a href=\"[MySBB]change_url[/MySBB]\">[MySBB]change_url[/MySBB]</a><br /><br />If you do not request a password change please click on the following link to cancel your order: <a href=\"[MySBB]cancel_url[/MySBB]\">[MySBB]cancel_url[/MySBB]</a><br /><br />Regards with management: [MySBB]board_title[/MySBB]'),(2,'Request to change your email address','welcome  [MySBB]username[/MySBB]<br /><br />You have requested to change your e-mail in the forum, to complete the steps and change it please click on this link: <a href=\"[MySBB]change_url[/MySBB]\">[MySBB]change_url[/MySBB]</a><br /><br />If you do not request an email change, please click on the following link to cancel your order: <a href=\"[MySBB]cancel_url[/MySBB]\">[MySBB]cancel_url[/MySBB]</a><br /><br />Regards with management: [MySBB]board_title[/MySBB]'),(3,'Report a bad topic','<p>Hello Dear Admin, A member of the visitors has reported the following topic: <a href=\"[MySBB]subject_url[/MySBB]\">[MySBB]subject_url[/MySBB]</a></p>'),(4,'Activation of membership','welcome  [MySBB]username[/MySBB] <br /><br />Thank you for registering at[MySBB]board_title[/MySBB] , Please activate the membership to be able to write in the forum and join the group of members<br /><br />To activate your membership please click on the following link:<br /> <a href=\"[MySBB]url[/MySBB]\">[MySBB]url[/MySBB]</a><br /><br />Regards with management: [MySBB]board_title[/MySBB]');
