INSERT INTO `pbb_template` VALUES (1,1,'address_bar_part1','<br />\n<div class=\"address_bar\">\n<div class=\"addr_bar\">\n<ol itemscope itemtype=\"https://schema.org/BreadcrumbList\" class=\"itemscope-nav\">\n<li itemprop=\"itemListElement\" itemscope\nitemtype=\"https://schema.org/ListItem\">\n<a itemprop=\"item\" href=\"index.php\">\n<span itemprop=\"name\">\n{$_CONF[&#39;info_row&#39;][&#39;title&#39;]}\n</span>\n</a>\n<meta itemprop=\"position\" content=\"1\" />\n</li>\n<div class=\"btn-nav\"></div>','<br />\n<div class=\"address_bar\">\n<div class=\"addr_bar\">\n<ol itemscope itemtype=\"https://schema.org/BreadcrumbList\" class=\"itemscope-nav\">\n<li itemprop=\"itemListElement\" itemscope\nitemtype=\"https://schema.org/ListItem\">\n<a itemprop=\"item\" href=\"index.php\">\n<span itemprop=\"name\">\n{$_CONF[&#39;info_row&#39;][&#39;title&#39;]}\n</span>\n</a>\n<meta itemprop=\"position\" content=\"1\" />\n</li>\n<div class=\"btn-nav\"></div>','template',1768808355,'PBBoard Solutions','3.0.4','PBBoard',0,1),(2,1,'address_bar_part2','</ol>\n</div>\n</div>\n<br />\n<br />\n{template}side_list{/template}','</ol>\n</div>\n</div>\n<br />\n<br />\n{template}side_list{/template}','template',1768808355,'PBBoard Solutions','3.0.4','PBBoard',0,1),(3,1,'add_attach_pm','<style>\n.file-preview {\n    display: inline-block;\n    font-size: 159px;\n    color: #0098DB;\n    margin-left: 1px;\n}\n.trash {\n  font-size: 15px;\n  color: #fff;\n  font-weight: normal;\n}\n</style>\n<ul style=\"list-style: none;display: inline-block;text-align: right;\" >\n{Des::while}{PmAttachList}\n<li class=\"attachmentInsert\">\n<div class=\"container\">\n<?php\nif ($PowerBB->_CONF[&#39;template&#39;][&#39;while&#39;][&#39;PmAttachList&#39;][$this->x_loop][&#39;extension&#39;] == (&#39;jpeg&#39;)\nor $PowerBB->_CONF[&#39;template&#39;][&#39;while&#39;][&#39;PmAttachList&#39;][$this->x_loop][&#39;extension&#39;] == (&#39;jpg&#39;)\nor $PowerBB->_CONF[&#39;template&#39;][&#39;while&#39;][&#39;PmAt