[&#39;upload_attach_num&#39;]};\nif (x <= up_max)\n{\n$(\".more_attach_tr\").hide();\n$(\"#add_attach_table\").append(&#39;<tr class=\"center_text_align\"><td class=\"row1 rows_space\"><fieldset><legend>{$lang[&#39;review_file&#39;]}</legend><span class=\"r-right\"><input name=\"files[]\" type=\"file\" id=\"attach&#39; + x + &#39;\" size=\"50\" /></span><span class=\"l-left\"></span></fieldset></td></tr>&#39;);\n$(\"#add_attach_table\").append(&#39;<tr class=\"more_attach_tr center_text_align\"><td class=\"row1 rows_space\" colspan=\"2\"><input type=\"button\" name=\"more_attach\" class=\"more_attach_class\" value=\"{$lang[&#39;more_attach_file&#39;]}\" /></td></tr>&#39;);\n$(\"#files\" + x).focus();\n$(\".more_attach_class\").click(function() { AddMoreAttach(x) });\nif (x == up_max)\n{\n$(\".more_attach_tr\").hide();\n}\n}\n}\nfunction Ready()\n{\n$(\"#attach_table\").hide();\n$(\".more_attach_class\").click(function() { AddMoreAttach(1) });\n}\n$(document).ready(Ready);\n</script>\n<form name=\"topic\" method=\"post\" enctype=\"multipart/form-data\" action=\"index.php?page=attachments&amp;add_start=1&amp;section={$section}\">\n<table class=\"border wd100 brd1 clpc0 a-center\" id=\"add_attach_table\">\n<tr class=\"center_text_align\">\n<td class=\"tcat\" colspan=\"2\">\n{$lang[&#39;attachments&#39;]}\n</td>\n</tr>\n<tr class=\"center_text_align\">\n<td class=\"row1 rows_space\" colspan=\"2\">\n<br />\n{$lang[&#39;ex_list&#39;]}\n{Des::while}{ExList}\n{$ExList[&#39;Ex&#39;]}\n{/Des::while}\n</td>\n</tr>\n<tr class=\"center_text_align\">\n<td class=\"row1 rows_space\" colspan=\"2\">\n<strong>{$lang[&#39;upload_attachments_nm&#39;]}\n{$_CONF[&#39;group_info&#39;][&#39;upload_attach_num&#39;]}</strong>\n</td>\n</tr>\n<div id=\"attach_table\">\n<tr class=\"center_text_align\">\n<td class=\"row1 rows_space\">\n<fieldset>\n<legend>{$lang[&#39;review_file&#39;]}</legend>\n<span class=\"r-right\">\n<input name=\"files[]\" type=\"file\" value=\"\" size=\"50\" />\n</span>\n<s