ta).find(&#39;#online_count_val&#39;).text() || \"1\";\n            $(\"#m_count\").text(count);\n        });\n    }\n\n    $(document).ready(function() {\n        read_cont();\n        read_users();\n        setInterval(read_cont, waittime);\n        setInterval(read_users, 20000);\n\n        $(document).on(&#39;keydown&#39;, &#39;#box_text&#39;, function(e) {\n            if(e.which == 13 && !e.shiftKey) {\n                e.preventDefault();\n                AjaxInsertChat();\n                return false;\n            }\n        });\n\n        $(document).on(&#39;mousedown&#39;, function(e) {\n            if (!$(e.target).closest(&#39;#smile_box, img[onclick*=\"smile_box\"]&#39;).length) {\n                $(&#39;#smile_box&#39;).removeClass(&#39;active&#39;);\n            }\n        });\n\n        $(document).one(&#39;mousedown touchstart&#39;, function() {\n            isAudioAllowed = false;\n        });\n    });\n</script>\n</body>\n</html>\n{/if}','template',1768808355,'PBBoard Solutions','3.0.4','PBBoard',0,1),(35,1,'editor_js','<link rel=\"stylesheet\" href=\"{$ForumAdress}look/sceditor/minified/themes/default.min.css\" id=\"theme-style\" />\n<script src=\"{$ForumAdress}look/sceditor/minified/formats/bbcode.js\"></script>\n<script src=\"{$ForumAdress}look/sceditor/minified/PBB_bbcode.js\"></script>\n<script src=\"{$ForumAdress}look/sceditor/minified/plugins/undo.js\"></script>\n<script src=\"look/sceditor/languages/{$_CONF[&#39;info_row&#39;][&#39;content_language&#39;]}.js\"></script>\n<script type=\"text/javascript\" src=\"{$ForumAdress}includes/js/IEprompt.js\"></script>\n<script type=&#39;text/javascript&#39;>\n{if {$_CONF[&#39;info_row&#39;][&#39;content_language&#39;]} != &#39;ar&#39;}\nfunction iePrompt(str){\nvar settings = \"dialogWidth: 290px; dialogHeight: 160px; center: yes; edge: raised; scroll: no; status: no;\";\nreturn window.showModalDialog(\"includes/js/iePrompt_en.htm\", str, settings);\n}\n{else}\nfunction iePrompt(str){\nvar settings 