rs\" class=\"border wd100 brd1 clpc0\">\n<tr>\n<td class=\"tcat\" colspan=\"2\">\n{$lang[&#39;Data_transmission&#39;]}\n</td>\n</tr>\n<tr>\n<td class=\"row1 rows_space\">\n{$lang[&#39;Send_to&#39;]}\n</td>\n<td class=\"row1\">\n<input name=\"to[]\" value=&#39;{$to}&#39; type=\"text\" />\n</td>\n</tr>\n<tr class=\"more_tr\">\n<td class=\"row1 center_text_align\" colspan=\"2\">\n<input name=\"more_resiver\" class=\"more_resiver_id\" type=\"button\" value=\"{$lang[&#39;Add_more_recipients&#39;]}\" />\n</td>\n</tr>\n</table>\n</div>\n<br />\n<div class=\"center_text_align\">\n<table class=\"border wd100 brd1 clpc0\">\n<tr>\n<td class=\"tcat\" colspan=\"2\">\n{$lang[&#39;message&#39;]}\n</td>\n</tr>\n</tr>\n<td class=\"row1 rows_space\">\n{$lang[&#39;PmTitle&#39;]}\n</td>\n<td class=\"row1\">\n<input name=\"title\" value=\"{$send_title}\" type=\"text\" class=\"max-input\" size=\"35\" />\n</td>\n</tr>\n<tr>\n<td class=\"row1 rows_space\" colspan=\"2\">\n<div id=\"none\">\n<div class=\"center_text_align\">\n<table class=\"wd98 brd1 clpc0\" style=\"border-collapse: collapse\">\n<tr>\n<td class=\"editortoolbar va-t\">\n{template}editor_js{/template}\n</td>\n</tr>\n<?php if ($PowerBB->_CONF[&#39;template&#39;][&#39;_CONF&#39;][&#39;group_info&#39;][&#39;upload_attach&#39;] == &#39;1&#39;) {  ?>\n<tr>\n<td class=\"row1\">\n<script type=\"text/javascript\" src=\"{$ForumAdress}includes/js/jquery.form.min.js\"></script>\n<div id=\"message\"></div>\n<div id=\"progress-div\" style=\"display:none;\"><div id=\"progress-bar\"></div></div>\n <div id=\"targetLayer\"></div>\n<div id=\"targetood\">\n{template}add_attach_pm{/template}\n</div>\n<br />\n<a title=\"{$lang[&#39;Add_attachments&#39;]}\" id=\"upload_link\" class=\"Button_public\" target=\"_blank\">\n<i class=\"fa fa-paperclip\"></i> {$lang[&#39;Add_attachments&#39;]}\n</a>\n\n</td>\n</tr>\n{/if}\n\n<tr>\n<td class=\"editoricon va-t\" colspan=\"2\">\n{template}iconbox{/template}\n</td>\n</tr>\n</table>\n</div>\n</td>\n</tr>\n\n<t