plupload/jquery_ui_plupload/css/jquery-ui.css\" type=\"text/css\" />\n<link rel=\"stylesheet\" href=\"{$ForumAdress}applications/core/plupload/jquery_ui_plupload/css/jquery_ui_plupload.css\" type=\"text/css\" media=\"screen\" />\n\n<div id=\"drag_position\">\n\n<style>\n#drag_position {display:none;}\n.information , .app_button{white-space: normal; display:inline; max-width: 65%;}\n#el_ement {cursor:move; height:200px; list-style:none;}\n#draggable {\nborder-radius: 4px 4px 0px 0px;\npadding: 15px;\ncolor: #fff;\nposition: relative;\nheight:200px;\n}\n.draggable {padding: 0px; margin: 0px; }\n.cover_photo{\nbackground-color: #F6F1F1;\nbackground-image:url({$image_path}/loading.gif);\nbackground-repeat: no-repeat;\nbackground-position:center;\ntext-align:center;\nwidth: 100%; height:200px;\n}\n\n#cover_photo_position {\nposition:absolute;\nbackground: rgba(0, 0, 0, 0.5) none repeat scroll 0% 0%;\nopacity: 0.6;\ncolor: #FFF;\n}\n\n</style>\n<script type=\"text/javascript\">\n$(document).ready(function(drag) {\n$(\"#element\").draggable({\ncontainment: &#39;#draggable&#39;,\nscroll: false\n}).mousemove(function(){\nvar coord = $(this).position();\nvar width = $(this).width();\nvar height = $(this).height();\n$(\"li.position\").text( \"(\" + coord.left + \",\" + coord.top + \")\" );\n$(\"li.size\").text( \"(\" + width + \",\" + height + \")\" );\n\nvar data = {};\ndata[&#39;left&#39;]    =     coord.left;\ndata[&#39;top&#39;]    =    coord.top;\ndata[&#39;width&#39;]    =    width;\ndata[&#39;height&#39;]    =    height;\ndata[&#39;layout&#39;]    =    1;\nvar AjaxState = {ajaxSend : $(\"#cover_photo_position_status\")};\n$.post(\"{$ForumAdress}includes/upload.php\",data,function( data ) {$(\"#cover_photo_position_status\" ).html( data );});\n})\n});\n</script>\n\n\n<div id=\"draggable\" class=\"pp-name\" title=\"{$lang[&#39;cover_photo_position&#39;]}\">\n<div class=\"ui-widget-header\">\n<a class=\"app_button Button_overlaid\" id=\"cover_photo_position\">\n<i class=\"fa fa-arrows-alt\"></i>&nbsp;<span class=\"Responsive_hidePhone Responsive_inline\">{$lang[&#39;save_photo_position&#39;]}</span>\n</a>\n<ul id=\"el_ement\" class=\"draggable\">\n<li class=\"cover_photo\">\n\n</li>\n<li class=\"position\"></li>\n<li class=\"size\"></li>\n</ul>\n</div>\n</div>\n\n</div>\n\n<script type=\"text/javascript\" src=\"{$ForumAdress}applications/core/plupload/plupload_full_min.js\"></script>\n<script type=\"text/javascript\" src=\"{$ForumAdress}applications/core/plupload/jquery_ui_plupload/jquery_ui_plupload.js\"></script>\n<script type=\"text/javascript\" src=\"applications/core/plupload/i18n/{$_CONF[&#39;info_row&#39;][&#39;content_language&#39;]}.js\"></script>\n\n{if {$MemberInfo[&#39;profile_cover_photo&#39;]} != &#39;&#39;}\n<style>\n#PageHead_special {\nbackground-color: #222;\n{$MemberInfo[&#39;profile_cover_photo_position&#39;]}\nposition: relative;\nbackground-image: url({$MemberInfo[&#39;profile_cover_photo&#39;]});\nbackground-position: center top;\nbackground-size: 100% 100%;\nbackground-repeat: no-repeat;\nborder-radius: 3px;\nborder: 1px solid #AAC9DC;\n}\n</style>\n{else}\n<style>\n#PageHead_special {\nbackground-color: #222;\nposition: relative;\nbackground-image: url(download/upload_cover_photo/default.jpg);\nbackground-position: center top;\nbackground-size: 100% 100%;\nbackground-repeat: no-repeat;\nborder-radius: 3px;\nborder: 1px solid #AAC9DC;\n}\n</style>\n{/if}\n{/if}\n<div class=\"pp-name\" id=\"PageHead_special\">\n<ul class=&#39;rUlRow&#39;>\n<li class=\"UserPhoto_xlarge r-right\" style=\"display: inline-block;\">\n{if {$_CONF[&#39;info_row&#39;][&#39;allow_avatar&#39;]}}\n{if {$MemberInfo[&#39;avater_path&#39;]} != &#39;&#39;}\n<a href=\"{$MemberInfo[&#39;avater_path&#39;]}\" >\n<img src=\"{$MemberInfo[&#39;avater_path&#39;]}\" class=\"brd0\" title=\"{$lang[&#39;Picture&#39;]}\n{$MemberInfo[&#39;username&#39;]}\n{$lang[&#39;Personal&#39;]}\"\nalt=\"{$lang[&#39;Picture&#39;]}\n{$MemberInfo[&#39;username&#39;]}\n{$lang[&#39;Personal&#39;]}\" /></a>\n{else}\n<a href=\"{$image_path}/\n{$_CONF[&#39;info_row&#39;][&#39;default_avatar&#39;]}\">\n<img src=\"{$image_path}/\n{$_CONF[&#39;info_row&#39;][&#39;default_avatar&#39;]}\" class=\"brd0\"\nalt=\"{$lang[&#39;no_photo&#39;]}\" />\n</a>\n{/if}\n{/if}\n</li>\n<li class=\"user_style_title r-right\" style=\"display: inline-block;\">\n<h3 >{$MemberInfo[&#39;username_style_cache&#39;]}</h3>\n{if {$GroupInfo[&#39;usertitle_change&#39;]} == &#39;1&#39;}\n <strong>{$Usertitle}</strong>\n{else}\n<strong>{$MemberInfo[&#39;user_title&#39;]}</strong>\n{/if}\n<br />\n<img class=\"rating brd0\" alt=\"rating\" src=\"{$user_ratings}\" />\n<br />\n<b class=\"user_online\">\n{if {$user_online}}\n<i title=\"Online\" class=\"Online fa fa-dot-circle-o\" aria-hidden=\"true\"></i>\n{else}\n <i title=\"Offline\" class=\"Offline fa fa-dot-circle-o\" aria-hidden=\"true\"></i>\n{/if}\n</b>\n</li>\n<li class=\"information_user break\">\n{if {$MemberInfo[&#39;user_info&#39;]} != &#39;&#39;}\n<div class=\"information_user_info\">\n<i class=\"fa fa-info-circle\"></i>\n<span class=\"dirc\" title=\"{$lang[&#39;About_Me&#39;]}\">\n<?php echo $PowerBB->_CONF[&#39;template&#39;][&#39;MemberInfo&#39;][&#39;user_info&#39;] = wordwrap($PowerBB->_CONF[&#39;template&#39;][&#39;MemberInfo&#39;][&#39;user_info&#39;], &#39;900&#39;, \"\n\", true); ?>\n</span>\n</div>\n{/if}\n{if {$MemberInfo[&#39;user_website&#39;]} != &#39;&#39; and {$MemberInfo[&#39;user_website&#39;]} != &#39;http://&#39;}\n<div class=\"information_user_website\">\n<i class=\"fa fa-link\"></i>\n <a title=\"{$lang[&#39;user_website&#39;]}\" target=\"_blank\"  class=\"dirc\" href=\"{$MemberInfo[&#39;user_website&#39;]}\">\n{$lang[&#39;Visit_my_website&#39;]}\n</a>\n</div>\n{/if}\n</li>\n<li>\n<?php if($PowerBB->_CONF[&#39;template&#39;][&#39;MemberInfo&#39;][&#39;username&#39;] == $PowerBB->_CONF[&#39;member_row&#39;][&#39;username&#39;]){ ?>\n\n<script type=\"text/javascript\">\n$(document).ready(function() {\n$(&#39;#pbb_upload_photo&#39;).click(function(){\n$(this).next(&#39;#pbb_dialog_upload_photo&#39;).slideToggle();\n$(\"#pbb_dialog_upload_photo\").css(&#39;display&#39;, &#39;block&#39;);\n$(this).toggleClass(&#39;dialog_upload_photo&#39;);\n\nif ($(this).hasClass(&#39;dialog_upload_photo&#39;)) $(this).find(&#39;s&#39;).html(&#39;?&#39;)\nelse $(this).find(&#39;s&#39;).html(&#39;?&#39;)\n})\n\n$(&#39;#dialog_close&#39;).click(function(){\n$(this).next(&#39;#pbb_dialog_upload_photo&#39;).slideToggle();\n$(\"#pbb_dialog_upload_photo\").css(&#39;display&#39;, &#39;none&#39;);\n$(this).toggleClass(&#39;dialog_upload_photo&#39;);\n\nif ($(this).hasClass(&#39;dialog_upload_photo&#39;)) $(this).find(&#39;s&#39;).html(&#39;?&#39;)\nelse $(this).find(&#39;s&#39;).html(&#39;?&#39;)\n})\n\n$(\"#filelist_browse\").click(function(){\n$(\"#cover_browse\").click();\n$(this).toggleClass(&#39;acover_photo&#39;);\n\nif ($(this).hasClass(&#39;acover_photo&#39;)) $(this).find(&#39;s&#39;).html(&#39;?&#39;)\nelse $(this).find(&#39;s&#39;).html(&#39;?&#39;)\n})\n\n});\n</script>\n<ul class=\"Button_split\" id=\"elEditProfile\">\n<li>\n<a class=\"app_button Button_overlaid\" id=\"eledit_photo\">\n<i class=\"fa fa-picture-o\"></i>&nbsp;<span class=\"Responsive_hidePhone Responsive_inline\">&nbsp;&nbsp;{$lang[&#39;cover_photo&#39;]}&nbsp;<i class=\"fa fa-caret-down\"></i></span>\n</a>\n<div id=\"eledit_photo_menu\">\n<ul class=\"PBBMenu PBBMenu_auto PBBMenu_bottomCenter\">\n<li class=\"PBBMenu_item\">\n<a href=\"index.php?page=ajax&amp;coverPhotoRemove=1\" onclick=\"return confirm(&#39;{$lang[&#39;confirm&#39;]}&#39;)\">{$lang[&#39;remove_cover_photo&#39;]}</a>\n</li>\n<!--\n<li class=\"PBBMenu_item\">\n<a data-action=\"positionCoverPhoto\">{$lang[&#39;cover_photo_position&#39;]}</a>\n</li>\n-->\n<li class=\"PBBMenu_item\">\n<a id=\"pbb_upload_photo\" href=\"#pbb_upload_photo\">{$lang[&#39;upload_cover_photo&#39;]}</a>\n</li>\n</ul>\n</div>\n</li>\n</ul>\n{template}profile_cover_photo_upload{/template}\n{/if}\n\n{if {$_CONF[&#39;member_permission&#39;]}}\n<?php if($PowerBB->_CONF[&#39;template&#39;][&#39;MemberInfo&#39;][&#39;username&#39;] != $PowerBB->_CONF[&#39;member_row&#39;][&#39;username&#39;]){ ?>\n<li class=\"l-left\">\n<div class=\"Button_split\">\n{if {$is_friend}}\n<a class=\"app_button Button_overlaid\" id=\"remove_friend\">\n<i class=\"fa fa-check\"></i>&nbsp;<span class=\"Responsive_hidePhone Responsive_inline\">&nbsp;&nbsp;{$lang[&#39;friends&#39;]}&nbsp;<i class=\"fa fa-caret-down\"></i></span>\n</a>\n<div id=\"friend_menu\">\n<ul class=\"PBBMenu PBBMenu_auto PBBMenu_bottomCenter\">\n<li class=\"PBBMenu_item\">\n<a href=\"index.php?page=usercp&amp;options=1&amp;friends=1&amp;del=1&amp;id={$friendship_id}\"\nonclick=\"return confirm(&#39;{$lang[&#39;confirm&#39;]}&#39;)\"><i class=\"fa fa-chain-broken\"></i>&nbsp;{$lang[&#39;remove_friend_1&#39;]}&nbsp;{$MemberInfo[&#39;username&#39;]}&nbsp;{$lang[&#39;remove_friend_2&#39;]}</a>\n</li>\n</ul>\n</div>\n{else}\n<a href=\"index.php?page=usercp&amp;options=1&amp;friends=1&amp;add=1&amp;username_friend={$MemberInfo[&#39;username&#39;]}\" id=\"add_friend\" class=\"app_button Button_overlaid\" rel=\"nofollow\">\n<i class=\"fa fa-user-plus\"></i>&nbsp;<span class=\"Responsive_hidePhone Responsive_inline\">&nbsp;&nbsp;{$lang[&#39;add_friend&#39;]}&nbsp;</span>\n</a>\n{/if}\n</div>\n</li>\n{/if}\n{/if}\n<?php if($PowerBB->_CONF[&#39;template&#39;][&#39;MemberInfo&#39;][&#39;username&#39;] == $PowerBB->_CONF[&#39;member_row&#39;][&#39;username&#39;]){ ?>\n<li class=\"management_profile l-left\">\n<a class=\"app_button\" href=\"index.php?page=usercp&amp;control=1&amp;info=1&amp;main=1\" title=\"{$lang[&#39;Management_Profile&#39;]}\">\n{$lang[&#39;Management_Profile&#39;]}\n</a>\n</li>\n{/if}\n</ul>\n</div>\n\n<!-- table --><div style=\"width:100%; border-spacing: 1px;\" class=\"table\">\n<dl>\n<dt></dt>\n<dd class=\"v-align-t prof-right\">\n{template}stuff_profile{/template}\n</dd>\n<dd class=\"v-align-t prof-left\">\n<br />\n<br />\n{if {$superadministrators}}\n<?php if($PowerBB->_CONF[&#39;template&#39;][&#39;MemberInfo&#39;][&#39;username&#39;] != $PowerBB->_CONF[&#39;member_row&#39;][&#39;username&#39;]){ ?>\n{template}login_admittance{/template}\n{/if}\n{/if}\n{if {$while[&#39;extrafield&#39;]}}\n{if is_array({$while[&#39;extrafield&#39;]})==true }\n<table class=\"border wd98 brd1 clpc0 a-center\">\n<tr>\n<td class=\"tcat wd60\" colspan=\"2\">\n{$lang[&#39;Additional_information&#39;]}\n</td>\n</tr>    {Des::while}{extrafield}\n<tr>\n<td class=\"row1 wd38\">\n{$extrafield[&#39;name&#39;]}\n</td>\n<td class=\"row1 wd60\">\n<?php if($PowerBB->_CONF[&#39;template&#39;][&#39;MemberInfo&#39;][$PowerBB->_CONF[&#39;template&#39;][&#39;while&#39;][&#39;extrafield&#39;][$this->x_loop][&#39;name_tag&#39;]]){ ?>\n<?php $PowerBB->_CONF[&#39;template&#39;][&#39;MemberInfo&#39;][$PowerBB->_CONF[&#39;template&#39;][&#39;while&#39;][&#39;extrafield&#39;][$this->x_loop][&#39;name_tag&#39;]] = $PowerBB->functions->CleanVariable($PowerBB->_CONF[&#39;template&#39;][&#39;MemberInfo&#39;][$PowerBB->_CONF[&#39;template&#39;][&#39;while&#39;][&#39;extrafield&#39;][$this->x_loop][&#39;name_tag&#39;]],&#39;html&#39;); ?>\n<?php echo $PowerBB->_CONF[&#39;template&#39;][&#39;MemberInfo&#39;][$PowerBB->_CONF[&#39;template&#39;][&#39;while&#39;][&#39;extrafield&#39;][$this->x_loop][&#39;name_tag&#39;]]; ?>\n<?php }else{ ?>\n{$lang[&#39;did_not_say&#39;]}\n<?php } ?>\n</td>\n</tr>\n{/Des::while}  </table>\n{/if}\n<br />\n{/if}\n{if {$MemberInfo[&#39;profile_viewers&#39;]} == &#39;1&#39;}\n<!-- Start Users Profile Viewers -->\n<table class=\"border wd98 brd1 clpc0 a-center\">\n<tr>\n<td class=\"tcat wd60\" colspan=\"1\">\n{$lang[&#39;profile_viewers&#39;]}\n</td>\n</tr>\n<tr>\n<td class=\"row1 wd60\">\n<div class=\"smallfont\">\n{if {$no_viewers}}\n{$lang[&#39;no_profile_viewers&#39;]}\n{else}\n{$lang[&#39;last_20_visits_profile&#39;]}<br /><br />\n{/if}\n{Des::while}{viewersList}\n<a href=\"index.php?page=profile&amp;show=1&amp;id={$viewersList[&#39;id&#39;]}\"\n{if {$show_visit_number}}\ntitle=\"{$lang[&#39;linkvisitor&#39;]} ({$viewersList[&#39;viewer_user_counter&#39;]})\"{/if}>\n{$viewersList[&#39;username&#39;]}\n</a>&nbsp;\n{/Des::while}\n</td>\n</tr>\n<tr>\n<td class=\"row1 wd60\">\n<div class=\"smallfont\">\n<?php $PowerBB->_CONF[&#39;template&#39;][&#39;_CONF&#39;][&#39;lang&#39;][&#39;this_page_visited_guest&#39;] = str_ireplace(&#39;{1}&#39;,$PowerBB->_CONF[&#39;template&#39;][&#39;view_page_num&#39;],$PowerBB->_CONF[&#39;template&#39;][&#39;_CONF&#39;][&#39;lang&#39;][&#39;this_page_visited_guest&#39;]); ?>\n<b>{$lang[&#39;this_page_visited_guest&#39;]}</b>\n</div>\n</td>\n</tr>\n</table>\n<!-- End Users Profile Viewers -->\n{/if}\n{if {$_CONF[&#39;info_row&#39;][&#39;allow_apsent&#39;]} == &#39;1&#39;}\n{if {$MemberInfo[&#39;away&#39;]} == 1}\n<br />\n<table class=\"border wd98 brd1 clpc0 a-center\">\n<tr>\n<td class=\"tcat wd60\">\n{$MemberInfo[&#39;username&#39;]}\n{$lang[&#39;Absent_now&#39;]}\n</td>\n</tr>\n<tr>\n<td class=\"row1 wd60 break\">\n{$lang[&#39;Reason_for_absence&#39;]}\n{$MemberInfo[&#39;away_msg&#39;]}\n</td>\n</tr>\n</table>\n<br />\n{/if}\n{/if}\n{if {$Awards_nm} > &#39;0&#39;}\n<br />\n<table class=\"border center_text_align wd98 brd1 clpc0 a-center user_awards\" style=\"table-layout: fixed;\">\n<tr>\n<td class=\"tcat wd60\">\n{$lang[&#39;awards&#39;]}:{$Awards_nm}\n</td>\n</tr>\n{Des::while}{AwardsList}\n<tr>\n<td class=\"tbar_writer_info center_text_align wd90\">\n{$AwardsList[&#39;award&#39;]}\n<br />\n<a href=\"{$AwardsList[&#39;award_path&#39;]}\" class=\"resize_img\">\n<img title=\"{$AwardsList[&#39;award&#39;]}\" src=\"{$AwardsList[&#39;award_path&#39;]}\" alt=\"{$AwardsList[&#39;award&#39;]}\" class=\"brd0\" />\n</a><br />\n</td>\n</tr>\n{/Des::while}\n</table>\n{/if}\n</dd>\n</dl>\n</div><!-- /table -->\n<br /><br />\n\n\n\n<script type=\"text/javascript\">\n// Initialize the widget when the DOM is ready\n$(function() {\n$(\"#filelist\").plupload({\n// General settings\nruntimes : &#39;html5,flash,silverlight,html4&#39;,\nurl : &#39;{$ForumAdress}includes/upload.php&#39;,\nunique_names: true,\n// User can upload no more then 20 files in one go (sets multiple_queues to false)\nmax_file_count: 1,\n\nchunk_size: &#39;1mb&#39;,\n\n// Resize images on clientside if we can\nresize : {\nwidth : 700,\nheight : 300,\nquality : 90,\ncrop: true // crop to exact dimensions\n},\n\nfilters : {\n// Maximum file size\nmax_file_size : &#39;1mb&#39;,\n// Specify what files to browse for\nmime_types: [\n{title : \"Image files\", extensions : \"jpg,gif,png,jpeg\"}\n]\n},\n\n// Rename files by clicking on their titles\nrename: true,\n\n// Sort files\nsortable: true,\nprevent_duplicates: true,\ninit : {\nFilesAdded: function(up, files) {\nvar max_files = 1;\nplupload.each(files, function(file) {\nif (up.files.length > max_files) {\nalert(\"{$lang[&#39;cover_photo_chaos_single_file&#39;]}\");\nup.removeFile(file);\n}\n});\nif (up.files.length >= max_files) {\n$(&#39;#pickfiles&#39;).hide();\n}\n},\nFilesRemoved: function(up, files) {\nif (up.files.length < max_files) {\n$(&#39;#pickfiles&#39;).fadeIn();\n}\n}\n},\n// Enable ability to drag&#39;n&#39;drop files onto the widget (currently only HTML5 supports that)\ndragdrop: true,\n\n// Views to activate\nviews: {\nlist: false,\nthumbs: true, // Show thumbs\nactive: &#39;thumbs&#39;\n},\n\n// Flash settings\nflash_swf_url : &#39;{$ForumAdress}applications/core/plupload/Moxie.swf&#39;,\n\n// Silverlight settings\nsilverlight_xap_url : &#39;{$ForumAdress}applications/core/plupload/Moxie.xap&#39;\n});\n\n\n});\n</script>','{template}address_bar_part1{/template}\n <li itemprop=\"itemListElement\" itemscope\nitemtype=\"https://schema.org/ListItem\">\n<a itemprop=\"item\" href=\"index.php?page=profile&amp;show=1&amp;id={$MemberInfo[&#39;id&#39;]}\">\n<span itemprop=\"name\">\n{$lang[&#39;View_Member_Profile&#39;]}\n {$MemberInfo[&#39;