39;1&#39; or{$_CONF[&#39;rows&#39;][&#39;group_info&#39;][&#39;vice&#39;]} == &#39;1&#39;}\n<div>\n<label for=\"rb_deletetype_2\">\n<input name=\"deletetype\" value=\"2\" id=\"rb_deletetype_2\" type=\"radio\">{$lang[&#39;delet_actual&#39;]}</label>\n</div>\n{else}\n{if {$_CONF[&#39;rows&#39;][&#39;group_info&#39;][&#39;group_mod&#39;]} == 1}\n{if {$_CONF[&#39;rows&#39;][&#39;group_info&#39;][&#39;del_subject&#39;]} == 0}\n<div>\n<label for=\"rb_deletetype_2\">\n<input name=\"deletetype\" value=\"2\" id=\"rb_deletetype_2\" disabled=\"disabled\" type=\"radio\">{$lang[&#39;delet_actual&#39;]}</label>\n</div>\n{else}\n<div>\n<label for=\"rb_deletetype_2\">\n<input name=\"deletetype\" value=\"2\" id=\"rb_deletetype_2\" type=\"radio\">{$lang[&#39;delet_actual&#39;]}</label>\n</div>\n{/if}\n{/if}\n{/if}\n</td>\n</tr>\n</table>\n</td>\n</tr>\n<tr>\n<td class=\"row1 rows_space wd60\" colspan=\"2\">\n<div class=\"center_text_align\">\n<input type=\"submit\" value=\"{$lang[&#39;Count&#39;]}\" /></div></td>\n</tr>\n</table></form>\n<br />\n<br />','template',1768808355,'PBBoard Solutions','3.0.4','PBBoard',0,1),(150,1,'subject_edit','<title>{$lang[&#39;edit_subject&#39;]} : {$SubjectInfo[&#39;title&#39;]}</title>\n<script language=\"javascript\">\nfunction ShowPollTable()\n{\nif ($(\"#poll_id\").is(\":checked\"))\n{\n$(\"#poll_table\").fadeIn();\n}\nelse\n{\n$(\"#poll_table\").fadeOut();\n}\n}\nfunction AddMoreAnswers(x)\n{\nx += 1;\nvar answers_max = 100;\n$(\"#poll_answers_count_id\").val(x);\n$(\".more_tr\").hide();\n$(\"#poll_question_answers\").append(&#39;<tr class=\"a-center\"><td class=\"row1\">{$lang[&#39;answers_number&#39;]}&#39; + x + &#39;</td><td class=\"row1\"><input name=\"answer[]\" type=\"text\" id=\"answer&#39; + x + &#39;\" /></td></tr>&#39;);\n$(\"#poll_question_answers\").append(&#39;<tr class=\"more_tr a-center\"><td class=\"row1\" colspan=\"2\"><input type=\"button\" name=\"more_answers\" class=\"more_answers_class\" value=\"{$lang[&#39;more_answers&#39;]}\" /></td></tr>&#39;);\n$(\"#answer\" + x).focus();\n$(\".more_answers_class\").click(function() { AddMoreAnswers(x) });\nif (function() { AddMoreAnswers(x) })\n{\n$(\".more_tr\").stopPropagation();\n}\n}\nfunction Ready()\n{\n$(\"#poll_table\").hide();\n$(\"#poll_id\").click(ShowPollTable);\n$(\".more_answers_class\").click(function() { AddMoreAnswers(2) });\n}\n$(document).ready(Ready);\n</script>\n{template}address_bar_part1{/template}\n<?php $PowerBB->_CONF[&#39;template&#39;][&#39;SubjectInfo&#39;][&#39;title&#39;] = $PowerBB->Powerparse->censor_words($PowerBB->_CONF[&#39;template&#39;][&#39;SubjectInfo&#39;][&#39;title&#39;]); ?>\n<?php $PowerBB->_CONF[&#39;template&#39;][&#39;SubjectpreviewInfo&#39;][&#39;title&#39;] = $PowerBB->Powerparse->censor_words($PowerBB->_CONF[&#39;template&#39;][&#39;SubjectpreviewInfo&#39;][&#39;title&#39;]); ?>\n<li itemprop=\"itemListElement\" itemscope\nitemtype=\"https://schema.org/ListItem\">\n<a itemprop=\"item\" href=\"index.php?page=forum&amp;show=1&amp;id={$SubjectInfo[&#39;section&#39;]}{$SubjectpreviewInfo[&#39;section&#39;]}\n{$password} \">\n<span itemprop=\"name\">{$section_info[&#39;title&#39;]}</span></a>\n<meta itemprop=\"position\" content=\"2\" />\n</li>\n<div class=\"btn-nav\"></div>\n<li itemprop=\"itemListElement\" itemscope\nitemtype=\"https://schema.org/ListItem\">\n{$lang[&#39;edit_Subject&#39;]} :\n<a itemprop=\"item\" href=\"index.php?page=topic&amp;show=1&amp;id={$SubjectInfo[&#39;id&#39;]}{$SubjectpreviewInfo[&#39;id&#39;]}\n{$password}\">\n<span itemprop=\"name\">\n{$SubjectInfo[&#39;title&#39;]}\n{$SubjectpreviewInfo[&#39;title&#39;]}\n</span>\n</a>\n<meta itemprop=\"position\" content=\"3\" />\n</li>\n{template}address_bar_part2{/template}\n{template}preview{/template}\n<form name=\"topic\" method=\"post\" action=\"{$edit_page}\">\n<input name=\"poll_answers_count\" id=\"poll_answers_count_id\" type=\"hidden\" value=\"2\">\n<table class=\"border wd98 brd1 clpc0 a-center\">\n<tr>\n<td class=\"tcat\">\n{$lang[&#39;text_Topic&#39;]}\n</td>\n</tr>\n<tr class=\"center_text_align\">\n<td class=\"row1 right_text_align\">\n{if {$section_info[&#39;active_prefix_subject&#39;]}}\n{$lang[&#39;prefix_subject&#39;]}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n<?php\n$excludedWords = array();\n$doubleAr = $PowerBB->_CONF[&#39;template&#39;][&#39;section_info&#39;][&#39;prefix_subject&#39;];\n$doubleAr = str_replace($PowerBB->_CONF[&#39;template&#39;][&#39;prefix_subject_prev&#39;],&#39;&#39;,$doubleAr);\n$doubleAr = str_replace($PowerBB->_CONF[&#39;template&#39;][&#39;SubjectInfo&#39;][&#39;prefix_subject&#39;],&#39;&#39;,$doubleAr);\n$prefix_subject = preg_split(\"#[\n]+#\", $doubleAr, -1, PREG_SPLIT_NO_EMPTY);\n$excludedWords = array_merge($excludedWords, $prefix_subject);\n?>\n<select name=\"prefix_subject\" style=\"font-weight: bold\">\n<option value=\"\">{$lang[&#39;no_prefix_subject&#39;]}</option>\n{if {$prefix_subject_prev} !=&#39;&#39;}\n<option value=\"{$prefix_subject_prev}\" selected=&#39;selected&#39;>{$prefix_subject_prev}</option>\n{/if}\n{if {$SubjectInfo[&#39;prefix_subject&#39;]} !=&#39;&#39;}\n<option value=\"{$SubjectInfo[&#39;prefix_subject&#39;]}\" selected=&#39;selected&#39;>{$SubjectInfo[&#39;prefix_subject&#39;]}</option>\n{/if}\n<?php\nfor ($x = 0; $x < @count($excludedWords); $x++)\n{\n$excludedWords[$x] = @trim($excludedWords[$x]);\nif($excludedWords[$x] !=&#39;&#39;)\n{\n$excludedWords[$x] = \"<option value=\".$excludedWords[$x].\">\".$excludedWords[$x].\"</option>\";\n}\necho $excludedWords[$x];\n}\necho &#39;</select>&#39;;\n?>\n<br />\n<br />\n{/if}\n\n{$lang[&#39;subject_title&#39;]} :\n<input name=\"title\" id=\"title\" type=\"text\" value=\"{$SubjectInfo[&#39;title&#39;]}{$title_prev}\" size=\"40\"\nonKeyDown=\"countChar(this)\"\nonKeyUp=\"countChar(this)\"\nonFocus=\"countChar(this)\" />\n<script type=&#39;text/javascript&#39;>\nfunction countChar(val) {\nvar len = val.value.length;\nif (len >= 100) {\nval.value = val.value.substring(0, {$_CONF[&#39;info_row&#39;][&#39;post_title_max&#39;]});\n} else {\n$(&#39;#charNum&#39;).text({$_CONF[&#39;info_row&#39;][&#39;post_title_max&#39;]} - len);\n}\n};\n</script>\n{if {$_CONF[&#39;info_row&#39;][&#39;subject_describe_show&#39;]} == 1}\n&nbsp;&nbsp;\n{$lang[&#39;subject_describe&#39;]}:&nbsp;\n  <input name=\"describe\" type=\"text\" value=\"{$SubjectInfo[&#39;subject_describe&#39;]}{$describe_prev}\" size=\"40\" />\n<span class=\"smallfont\">{$lang[&#39;Optional&#39;]}</span>\n{/if}\n<br />\n</td>\n</tr>\n<tr>\n<td class=\"row1\">\n<div id=\"none\">\n<div class=\"center_text_align\">\n<table class=\"wd100 brd0 clpc0\">\n<tr>\n<td class=\"editortoolbar va-t\">\n{template}editor_js{/template}\n<!-- action_find_addons_3 -->\n</td>\n</tr>\n<tr>\n<td class=\"row1\">\n<script type=\"text/javascript\" src=\"{$ForumAdress}includes/js/jquery.form.min.js\"></script>\n<div id=\"message\"></div>\n<div id=\"progress-div\" style=\"display:none;\"><div id=\"progress-bar\"></div></div>\n <div id=\"targetLayer\"></div>\n<div id=\"targetood\">\n{template}attach_list{/template}\n</div>\n<br />\n<a title=\"{$lang[&#39;Add_attachments&#39;]}\" id=\"upload_link\" class=\"Button_public\" target=\"_blank\">\n<i class=\"fa fa-paperclip\"></i> {$lang[&#39;Add_attachments&#39;]}\n</a>\n\n</td>\n</tr>\n<tr>\n<td class=\"editoricon va-t\" colspan=\"2\">\n<fieldset>\n<legend>{$lang[&#39;reason_edit&#39;]}</legend>\n<input name=\"reason_edit\" type=\"text\" value=\"{$reason_edit}\" size=\"38\" />\n</fieldset>\n{template}iconbox{/template}\n</td>\n</tr>\n</table></div>\n</div>\n</td>\n</tr>\n<tr>\n<td class=\"row1\">\n{if {$_CONF[&#39;info_row&#39;][&#39;allowed_emailed&#39;]} == &#39;1&#39; AND {$_CONF[&#39;member_permission&#39;]}}\n<input name=\"emailed\" id=\"emailed_id\" type=\"checkbox\" {if {$IsSubscribed}}checked=\"checked\"{/if}/>\n<label for=\"emailed_id\">{$lang[&#39;Enabled_to_be_notified_by_the_existence_of_new_replies&#39;]}</label></a>\n{/if}\n<?php\nif($PowerBB->_CONF[&#39;template